INSERT INTO questions ("unitId", question, options, "correctAnswer", correctAnswers, type, explanation) VALUES
('ich-guidelines', 'أي قسم في ICH يركز على اختبارات الثبات والشوائب؟', '["Safety (S)", "Quality (Q)", "Efficacy (E)", "Multidisciplinary (M)"]', '1', NULL, 'multiple', NULL);
INSERT INTO questions ("unitId", question, options, "correctAnswer", correctAnswers, type, explanation) VALUES
('validation-qualification', 'ما هو المفهوم الأساسي للتحقق (Validation) في الصناعة الدوائية؟', '["ضمان الجودة عن طريق فحص العينة النهائية فقط", "تقديم دليل موثق بأن العملية تؤدي باستمرار إلى النتائج المتوقعة", "إلغاء الحاجة إلى مختبرات مراقبة الجودة (QC)", "تسريع الإنتاج بغض النظر عن الجودة"]', '1', NULL, 'multiple', NULL),
('validation-qualification', 'ماذا يعني تأهيل التصميم (DQ)؟', '["توثيق أن تصميم المعدة أو المرفق مناسب للغرض المقصود ومتوافق مع GMP", "اختبار الجهاز الفعلي بعد شرائه في المصنع", "كتابة سجل تشغيلة المنتج (MBR)", "نظافة المعدات من الخارج"]', '0', NULL, 'multiple', NULL),
('validation-qualification', 'ما هي المرحلة التي تتأكد من أن المعدة قد تم توريدها وتركيبها كما ورد في التصميم وتوصيات المصنع؟', '["PQ", "OQ", "IQ", "DQ"]', '2', NULL, 'multiple', NULL),
('validation-qualification', 'أثناء تأهيل التشغيل (OQ)، يتم التحقق من:', '["أن جميع الفواتير مدفوعة للشركة المصنعة", "أن المعدة تعمل كما هو متوقع عبر جميع نطاقات التشغيل (Operating Ranges)", "أن المنتج النهائي يباع في السوق", "أن المشغلين يرتدون الزي الرسمي"]', '1', NULL, 'multiple', NULL),
('validation-qualification', 'تأهيل الأداء (PQ) يختلف عن (OQ) بأنه:', '["يختبر المعدة باستخدام الدفاتر والمستندات فقط", "يختبر المعدة باستخدام المنتج الفعلي (أو ما يماثله) وفي ظروف الإنتاج الحقيقية", "يختبر المعدة وهي فارغة (بدون منتج)", "يتم فقط من قبل الشركة المصنعة للمعدة"]', '1', NULL, 'multiple', NULL),
('validation-qualification', 'ما هو الهدف الرئيسي من "التحقق من التنظيف" (Cleaning Validation)؟', '["توفير الماء والصابون", "دليل موثق على إزالة الملوثات لمستويات آمنة محددة مسبقاً لمنع التلوث التبادلي", "تلميع المعدة لمنظرها الجمالي", "إعفاء العمال من مهام التنظيف"]', '1', NULL, 'multiple', NULL),
('validation-qualification', 'في التحقق من التنظيف، ماذا يعني مصطلح (Worst-Case Scenario)؟', '["أسوأ موظف في المصنع", "انقطاع الكهرباء أثناء الإنتاج", "اختيار المنتج الأصعب في التنظيف والأقوى فعالية لاختبار بروتوكول التنظيف عليه", "انتهاء صلاحية المنظف"]', '2', NULL, 'multiple', NULL),
('validation-qualification', 'من هو المسؤول الأساسي في المصنع عن الموافقة على خطة التحقق الشاملة (VMP)؟', '["قسم التسويق المبيعات", "الإدارة العليا ووحدة الجودة (Quality Unit)", "فنيو المختبر", "عمال المخازن"]', '1', NULL, 'multiple', NULL),
('validation-qualification', 'كيف يمكننا التحقق من أن طريقة التحليل المخبري (Analytical Method) صحيحة؟', '["بالتخمين والحدس", "عبر Method Validation لإثبات الدقة، والضبط، والنوعية، وغيرها من المعايير", "بسؤال مدير المختبر", "بتكرار الفحص مرتين فقط"]', '1', NULL, 'multiple', NULL),
('validation-qualification', 'التأهيل الرجعي (Retrospective Validation) يعني:', '["التنبؤ بجودة المنتجات المستقبلية", "الاعتماد على البيانات التاريخية المسجلة لعملية ما لإثبات استقرارها", "إعادة المعدات إلى المصنع", "مسح البيانات القديمة"]', '1', NULL, 'multiple', NULL),
('validation-qualification', 'بناءً على دراسة الحالة لماكينة الـ Blister، لماذا فشلت الماكينة أثناء الـ PQ رغم نجاحها في الـ OQ؟', '["لأن الـ OQ اختبر المعدة وهي تعمل فارغة أو بأدوات غير تماثلية كاملة، بينما وضعها الـ PQ تحت ظروف الإنتاج الحقيقي بأقراص حقيقية مختلفة السماكة.", "لأن التيار الكهربائي تعطل يومها.", "لأن مشغل الماكينة تعمد التخريب.", "لأن IQ لم يتم أساساً."]', '0', NULL, 'multiple', NULL),
('validation-qualification', 'هل يمكن الاستغناء عن الـ IQ إذا قمنا للتو بشراء معدة حديثة من شركة عالمية معروفة؟', NULL, 'false', NULL, 'tf', NULL),
('validation-qualification', 'يعتبر التحقق المستمر من العمليات (CPV) منهجاً حديثاً يضمن أن العملية تظل في حالة تحكم طوال دورة حياتها.', NULL, 'true', NULL, 'tf', NULL),
('validation-qualification', 'الوثيقة الرئيسية التي تصف استراتيجية التحقق لكامل المنشأة تسمى بـ الخطة [______] للتحقق (VMP).', NULL, NULL, ARRAY['الشاملة', 'الرئيسية', 'الرئيسي', 'master'], 'fill', NULL),
('validation-qualification', 'التأهيل الذي يثبت أن المعدة تم تركيبها بشكل صحيح وفق التوصيات الفنية هو الـ [___].', NULL, NULL, ARRAY['IQ', 'iq', 'تأهيل التركيب'], 'fill', NULL);
INSERT INTO questions ("unitId", question, options, "correctAnswer", correctAnswers, type, explanation) VALUES
('adv-validation', 'حسب إرشادات 2011، التحقق من العملية (Process Validation) أصبح يتكون من:', '["ثلاث دفعات تجريبية فقط", "دورة حياة تشمل التصميم والتأهيل والتحقق المستمر (CPV)", "فحص المنتج النهائي فقط", "كتابة تقرير واحد في السنة"]', '1', NULL, 'multiple', NULL);
INSERT INTO questions ("unitId", question, options, "correctAnswer", correctAnswers, type, explanation) VALUES
('gdp-basics', 'ما هو المبدأ الأساسي لشحن أدوية "Cold Chain" (سلسلة التبريد)؟', '["الشحن في أي درجة حرارة متاحة", "الحفاظ على درجة حرارة 2-8 مئوية طوال الرحلة وتوثيقها بمسجلات البيانات", "التجميد الدائم للأدوية حتى تصل للعميل", "استخدام صناديق كرتونية عادية"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'ماذا تعني "ممارسات التوزيع الجيد" (GDP)؟', '["توزيع الأموال على الموظفين", "نظام يضمن جودة المنتج الدوائي طوال سلسلة التوريد من المصنع للمريض", "طريقة لزيادة المبيعات", "قواعد لترتيب المكاتب"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'ما هي درجة الحرارة المعتادة لتخزين "الأدوية المبردة"؟', '["15-25 °C", "2-8 °C", "0-4 °C", "تحت الصفر دائماً"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'ما هو دور الـ Data Logger في الشحنات الدوائية المبردة؟', '["تبريد الشحنة", "تسجيل درجة الحرارة بشكل مستمر طوال الرحلة لإثبات الالتزام بالسلسلة", "الاتصال بالسائق", "قياس سرعة الشاحنة"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'أي مما يلي يعتبر علامة محتملة على "تزوير الدواء"؟', '["تغليف جديد ونظيف", "رقم دفعة مفقود أو غير مطابق أو تاريخ انتهاء ممسوح", "سعر مرتفع جداً", "وجود نشرة داخلية"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'مبدأ FIFO في المستودعات يعني:', '["الأغلى يباع أولاً", "ما يدخل أولاً يخرج أولاً (First In First Out)", "ما ينتهي أولاً يخرج أولاً (FEFO)", "تخزين عشوائي"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'يُعرّف "التتبع" (Traceability) في الـ GDP بأنه:', '["معرفة اسم السائق فقط", "القدرة على تتبع مسار الدواء من المنشأ للمريض وبالعكس عند الحاجة للسحب", "رسم خريطة للمستودع", "تسجيل عدد العينات الموزعة"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'ما هو الإجراء الصحيح عند اكتشاف دواء مشبوه بأنه مزور؟', '["بيعه بسرعة للتخلص منه", "عزله فوراً (Quarantine/Segregate) وإبلاغ الجهات الرقابية والمصنع", "وضعه في الثلاجة", "تجاهله"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'خريطة التوزيع الحراري للمستودع (Temperature Mapping) تهدف إلى:', '["تلوين الجدران", "تحديد النقاط الأكثر حرارة وبرودة لضمان وضع الأدوية في المناطق الآمنة", "زيادة الإضاءة", "تقليل عدد الرفوف"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'لماذا يُعتبر النقل الجوي والبري أحياناً خطراً على سلسلة التبريد؟', '["بسبب كثرة المطبات", "بسبب التعرض لدرجات حرارة خارجية متغيرة وضياع الشحنات في الجمارك", "لأن الطائرات تطير عالياً", "لأنها تستهلك وقوداً كثيراً"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'في دراسة حالة الأنسولين، لماذا تقرر إتلاف الشحنة رغم أنها قضت 4 ساعات فقط خارج الثلاجة؟', '["لأن الأنسولين رخيص", "لأن تقييم المخاطر واستشارة المصنع أثبتت أن تخطي درجة الحرارة (15 مئوية) قد يؤثر على فعالية الدواء ويؤذي المريض", "لأن الثلاجة كانت مكسورة", "لأن التاريخ كان قديماً"]', '1', NULL, 'multiple', NULL),
('gdp-basics', 'يسمح بتخزين الأدوية مع المواد الغذائية في نفس الثلاجة إذا كانت المساحة ضيقة.', NULL, 'false', NULL, 'tf', NULL),
('gdp-basics', 'يجب أن يكون لدى جميع الموزعين نظام للجرد يضمن عدم انتهاء صلاحية الأدوية في المخازن.', NULL, 'true', NULL, 'tf', NULL),
('gdp-basics', 'اختصار المبدأ الذي يضمن خروج الأدوية الأقرب للانتهاء أولاً هو الـ [____].', NULL, NULL, ARRAY['FEFO', 'فيفو'], 'fill', NULL),
('gdp-basics', 'درجة حرارة الغرفة الخاضعة للرقابة (Controlled Room Temp) هي [___] درجة مئوية.', NULL, NULL, ARRAY['15-25', '15 to 25'], 'fill', NULL);
INSERT INTO questions ("unitId", question, options, "correctAnswer", correctAnswers, type, explanation) VALUES
